import{z as s,x as A,o as i,c as B,q as p,j as l,D as e,d as r,s as t,S as o,b as n}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"Akra–Bazzi 对照","description":"","frontmatter":{"title":"Akra–Bazzi 对照","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/akra-bazzi.md","filePath":"cs/akra-bazzi.md","lastUpdated":1791413859000}'),d={name:"cs/akra-bazzi.md"};function T(_,a,b,h,m,g){const E=A("Mermaid");return i(),B("div",null,[a[2]||(a[2]=p('<h1 id="akra–bazzi-对照" tabindex="-1">Akra–Bazzi 对照 <a class="header-anchor" href="#akra–bazzi-对照" aria-label="Permalink to &quot;Akra–Bazzi 对照&quot;">​</a></h1><div class="epigraph"><p>子问题不必等分：只要切法渐近稳定，解仍由一项积分与临界幂 $n^p$ 决定。</p><footer>—— 据 Akra and Bazzi, On the solution of linear recurrence equations, 1998；CLRS 第 4 章对主定理的讨论整理</footer></div><p>上一课<a href="/cs/master-theorem">主定理</a>只收 \\(T(n)=aT(n/b)+f(n)\\)。三种情形已经能读归并与二分，但切块大小可以不同：\\(T(n)=T(\\lfloor n/3\\rfloor)+T(\\lceil 2n/3\\rceil)+\\Theta(n)\\) 没有单一的 \\(b\\)。本课不重证几何级数。缺口是一条对照公式，让后课分治在不等分时仍有阶，而不把每一道递归树重画成百科。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>主定理的 \\(a\\) 个子问题一律 \\(n/b\\)。实际切法常一边三分之一、一边三分之二，或再加一项 \\(T(n/4)\\)。叶子不再是整齐的 \\(n^{\\log_b a}\\)。缺口不是再发明大 \\(O\\)，而是承认：若 \\(T(n)=g(n)+\\sum_{i=1}^k a_i T(n/b_i)\\)（地板可忽略），存在唯一 \\(p\\) 使 \\(\\sum a_i b_i^{-p}=1\\)，则</p> \\[T(n)=\\Theta\\Bigl(n^p\\Bigl(1+\\int_1^n \\frac{g(u)}{u^{p+1}}\\,du\\Bigr)\\Bigr). \\]<p>\\(g\\) 多项式地小于、等于、大于 \\(n^p\\) 时，积分给出与主定理三种情形同类的主导项。规律性条件仍要：\\(g\\) 在多项式因子内不太振荡。</p><p><span class="marginnote">术语翻译：临界幂 \\(p\\) 就是「叶子层工作量」的阶——递归树最底那一层总共贡献多少。等分时它是 \\(\\log_b a\\)；不等分时切法五花八门，就用方程 \\(\\sum a_i b_i^{-p}=1\\) 把各分支按权重折算出同一个 \\(p\\)，可理解为「加权平均版的 \\(\\log_b a\\)」。</span></p><h3 id="对照不是第三套渐近记号" tabindex="-1">对照不是第三套渐近记号 <a class="header-anchor" href="#对照不是第三套渐近记号" aria-label="Permalink to &quot;对照不是第三套渐近记号&quot;">​</a></h3><p>\\(p\\) 就是不等分版的 \\(\\log_b a\\)。等分时 \\(k=1\\)、\\(a_1=a\\)、\\(b_1=b\\)，方程 \\(a b^{-p}=1\\) 解出 \\(p=\\log_b a\\)，积分退化成主定理。本课不换 \\(O\\)、\\(\\Theta\\) 的定义，只换临界指数的算法。</p><p><span class="marginnote">Akra–Bazzi 1998 处理线性递推的连续近似。CLRS 把主定理当特例，把地板、\\(\\pm 1\\) 丢进光滑性。后课只引用「先解 \\(p\\)，再看积分」，不把证明展开。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写出各 \\(a_i,b_i\\) 与合并项 \\(g\\)。数值或对数求解 \\(p\\)。比较 \\(g(n)\\) 与 \\(n^p\\)：积分收敛则 \\(T=\\Theta(n^p)\\)；对数发散则多 \\(\\log\\)；根上的 \\(g\\) 更大则 \\(T=\\Theta(g)\\)。替换法仍可验证猜出的阶。</p><p><span class="marginnote">数字实例：\\(T(n)=T(n/3)+T(2n/3)+\\Theta(n)\\) 时解 \\((1/3)^p+(2/3)^p=1\\)，代 \\(p=1\\) 恰好 \\(1/3+2/3=1\\)，故 \\(p=1\\)；\\(g(n)=n\\) 与 \\(n^1\\) 只差常数倍，积分发散成 \\(\\log\\)，得 \\(T=\\Theta(n\\log n)\\)。与等分的归并排序同阶——切歪了，代价没变。</span></p>',14)),(i(),l(o,null,{default:e(()=>[t(E,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20UNEQ%5B%22%E4%B8%8D%E7%AD%89%E5%88%86%E5%AD%90%E9%97%AE%E9%A2%98%22%5D%20--%3E%20P%5B%22%E8%A7%A3%20%CE%A3%20a_i%20%2F%20b_i%5Ep%20%3D%201%22%5D%0A%20%20P%20--%3E%20INT%5B%22%E7%A7%AF%E5%88%86%20g(u)%2Fu%5E%7Bp%2B1%7D%22%5D%0A%20%20INT%20--%3E%20TH%5B%22T(n)%20%E7%9A%84%20%CE%98%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n("p",null,"主定理能套时不必走积分。本课是它失效时的出口，不是默认第一步。",-1)),a[4]||(a[4]=n("h2",{id:"机制",tabindex:"-1"},[r("机制 "),n("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=n("p",null,"有了 \\(p\\)，后课写「一半再一半」或「三分之一加三分之二」都可以落成同一句话：临界幂由切法的加权平均决定。正确性仍走递归归纳，本课只管代价。也不要把 \\(p\\) 当成输入规模；它由算法的切法钉死。",-1)),a[6]||(a[6]=n("p",null,"拿到一条递推式，先分清它属于哪个家族，再决定用主定理、Akra–Bazzi 还是直接求和：",-1)),(i(),l(o,null,{default:e(()=>[t(E,{id:"mermaid-51",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%22%E9%80%92%E6%8E%A8%E5%BC%8F%E5%88%B0%E6%89%8B%22%5D%20--%3E%20Q1%7B%22%E5%AD%90%E9%97%AE%E9%A2%98%E8%A7%84%E6%A8%A1%E6%98%AF%20n%2Fb%20%E8%BF%98%E6%98%AF%20n-1%EF%BC%9F%22%7D%0A%20%20Q1%20--%3E%7C%22n%20-%201%EF%BC%8C%E5%87%8F%E8%80%8C%E6%B2%BB%E4%B9%8B%22%7C%20SUB%5B%22%E7%A7%AF%E5%88%86%E5%85%AC%E5%BC%8F%E4%B8%8D%E9%80%82%E7%94%A8%EF%BC%9A%E6%8C%89%E7%AD%89%E5%B7%AE%E6%95%B0%E5%88%97%E7%9B%B4%E6%8E%A5%E6%B1%82%E5%92%8C%22%5D%0A%20%20Q1%20--%3E%7C%22n%20%2F%20b%22%7C%20Q2%7B%22%E5%90%84%E5%88%86%E6%94%AF%E5%88%87%E6%B3%95%E7%9B%B8%E5%90%8C%E5%90%97%EF%BC%9F%22%7D%0A%20%20Q2%20--%3E%7C%22%E7%AD%89%E5%88%86%E5%90%8C%E4%B8%80%E4%B8%AA%20b%22%7C%20MT%5B%22%E4%B8%BB%E5%AE%9A%E7%90%86%EF%BC%9Ap%20%3D%20log_b%20a%22%5D%0A%20%20Q2%20--%3E%7C%22%E4%B8%8D%E7%AD%89%E5%88%86%22%7C%20AB%5B%22Akra%E2%80%93Bazzi%EF%BC%9A%E8%A7%A3%20%CE%A3%20a_i%20b_i%5E-p%20%3D%201%22%5D%0A%20%20MT%20--%3E%20G%5B%22%E6%AF%94%E8%BE%83%20g(n)%20%E4%B8%8E%20n%5Ep%20%E5%AE%9A%E4%B8%BB%E5%AF%BC%E9%A1%B9%22%5D%0A%20%20AB%20--%3E%20G%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=p('<p><span class="marginnote">常见误区：初学者容易以为 \\(p\\) 可以凑整或任选。实际上 \\(p\\) 由切法唯一钉死，通常不是整数——例如 \\((1/2)^p+(1/4)^p+(1/8)^p=1\\) 的解约是 0.88，只能数值求解；凑成 1 会把整个答案的阶读错。</span></p><p><span class="marginnote">为什么重要：先解 \\(p\\) 再看 \\(g\\) 的顺序不能反。若跳过 \\(p\\) 直接套「合并项主导」的直觉，会把 \\(T(n)=T(n/3)+T(2n/3)+\\Theta(n)\\) 误判成 \\(\\Theta(n)\\)，漏掉 \\(\\log\\) 因子——排序、中位数这类算法的真实代价就藏在这个因子里。</span></p><p>减而治之 \\(T(n)=T(n-1)+\\Theta(n)\\) 没有 \\(n/b_i\\) 形式，积分公式不适用，仍是等差求和。期望递归（随机切点）也不是本课对象。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证积分公式，不处理 \\(g\\) 在临界附近振荡的病态。也不把分治当作设计法讲完：切什么、合什么，下一课才命名。后课默认：等分先主定理；不等分先 Akra–Bazzi 的 \\(p\\)。</p><p>后课默认：谈到分治递归，阶可以读。分治三步本身是下一缺口。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>不等分递推用 \\(p\\) 满足 \\(\\sum a_i b_i^{-p}=1\\)，再看 \\(g\\) 的积分。</li><li>等分时退回主定理；减一与期望递归不在本课。</li><li>本课只给阶，不给分解–合并的正确性模板。</li><li>出处：Akra and Bazzi, 1998；CLRS 第 4 章。</li></ul>',8))])}const z=s(d,[["render",T]]);export{C as __pageData,z as default};
